package main

import (
	"archive/zip"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

const uploadDir = "/var/app/uploads"
const extractDir = "/var/app/extracted"

func main() {
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/upload", uploadHandler)
	http.HandleFunc("/extract", extractHandler)
	fmt.Println("Starting archive service on :8080")
	http.ListenAndServe(":8080", nil)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	file, header, err := r.FormFile("archive")
	if err != nil {
		http.Error(w, "Failed to read file", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// Only accept .zip files
	if !strings.HasSuffix(header.Filename, ".zip") {
		http.Error(w, "Only .zip files accepted", http.StatusBadRequest)
		return
	}

	os.MkdirAll(uploadDir, 0755)
	dst, err := os.Create(filepath.Join(uploadDir, header.Filename))
	if err != nil {
		http.Error(w, "Failed to save file", http.StatusInternalServerError)
		return
	}
	defer dst.Close()
	io.Copy(dst, file)

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(fmt.Sprintf(`{"saved":"%s"}`, header.Filename)))
}

func extractHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	filename := r.FormValue("filename")
	if filename == "" {
		http.Error(w, "filename required", http.StatusBadRequest)
		return
	}

	// Sanitize the filename parameter itself
	filename = filepath.Base(filename)
	archivePath := filepath.Join(uploadDir, filename)

	reader, err := zip.OpenReader(archivePath)
	if err != nil {
		http.Error(w, "Failed to open archive", http.StatusInternalServerError)
		return
	}
	defer reader.Close()

	os.MkdirAll(extractDir, 0755)

	var extracted []string
	for _, f := range reader.File {
		// Attempt to prevent directory traversal by cleaning the path
		cleanName := filepath.Clean(f.Name)
		// Note: filepath.Clean does NOT strip leading "../" sequences
		// when they resolve above the root - this is the vulnerability
		targetPath := filepath.Join(extractDir, cleanName)

		if f.FileInfo().IsDir() {
			os.MkdirAll(targetPath, f.Mode())
			continue
		}

		os.MkdirAll(filepath.Dir(targetPath), 0755)
		outFile, err := os.OpenFile(targetPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, f.Mode())
		if err != nil {
			continue
		}

		rc, err := f.Open()
		if err != nil {
			outFile.Close()
			continue
		}

		io.Copy(outFile, rc)
		rc.Close()
		outFile.Close()
		extracted = append(extracted, targetPath)
	}

	w.WriteHeader(http.StatusOK)
	w.Write([]byte(fmt.Sprintf(`{"extracted":%d}`, len(extracted))))
}
